"use client";

import type { ButtonHTMLAttributes } from "react";
import { useEffect, useState } from "react";
import { motion, useSpring } from "motion/react";
import "./magnetic-button.css";

export function MagneticButton({
  children,
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) {
  const [reduce, setReduce] = useState(false);
  const x = useSpring(0, { stiffness: 260, damping: 13, mass: 0.7 });
  const y = useSpring(0, { stiffness: 260, damping: 13, mass: 0.7 });
  useEffect(() => {
    const media = matchMedia("(prefers-reduced-motion:reduce)");
    const update = () => setReduce(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  useEffect(() => {
    if (reduce || props.disabled) {
      x.jump(0);
      y.jump(0);
    }
  }, [reduce, props.disabled, x, y]);
  return (
    <span
      className="forme-magnet"
      onPointerMove={(event) => {
        if (reduce || props.disabled || event.pointerType !== "mouse") return;
        const bounds = event.currentTarget.getBoundingClientRect();
        x.set((event.clientX - bounds.left - bounds.width / 2) * 0.22);
        y.set((event.clientY - bounds.top - bounds.height / 2) * 0.22);
      }}
      onPointerLeave={() => {
        x.set(0);
        y.set(0);
      }}
      onPointerCancel={() => {
        x.set(0);
        y.set(0);
      }}
    >
      <motion.span
        style={{ x, y }}
        whileTap={reduce || props.disabled ? undefined : { scale: 0.96 }}
        transition={{ type: "spring", stiffness: 420, damping: 14, mass: 0.55 }}
      >
        <button
          {...props}
          type={type}
          className={`forme-magnet-button ${className}`}
        >
          <span>{children}</span>
          <span className="forme-magnet-arrow" aria-hidden="true">
            ↗
          </span>
        </button>
      </motion.span>
    </span>
  );
}

.forme-magnet {
  display: inline-flex;
  padding: 18px;
  max-width: 100%;
}
.forme-magnet > span {
  display: inline-flex;
  max-width: 100%;
}
.forme-magnet-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  max-width: 100%;
  padding: 18px 25px;
  border: 1px solid currentColor;
  border-radius: 50px;
  background: var(--forme-button-bg, #242d25);
  color: var(--forme-button-color, #f3f3e8);
  font: inherit;
  font-size: 16px;
  cursor: pointer;
}
.forme-magnet-button > span:first-child {
  overflow-wrap: anywhere;
  text-align: left;
}
.forme-magnet-arrow {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  font-size: 22px;
  transition: transform 0.35s;
}
.forme-magnet-button:hover .forme-magnet-arrow {
  transform: rotate(45deg);
}
.forme-magnet-button:focus-visible {
  outline: 3px solid #617cf5;
  outline-offset: 5px;
}
.forme-magnet-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .forme-magnet-arrow {
    transition: none;
  }
  .forme-magnet-button:hover .forme-magnet-arrow {
    transform: none;
  }
}
